  warpStrength: f32,
  warpScale: f32,
  warpSpeed: f32,
  warpDepth: f32,

  circleRadius: f32,
  circleSoft: f32,
  circlePos: vec2f,

  rotation: f32,
  zoom: f32,

  col1: vec3f,
  col2: vec3f,
  col3: vec3f,
  col4: vec3f,
  saturation: f32,
  brightness: f32,
  contrast: f32,
  blendWidth: f32,
  colorShift: f32,
  highlightStr: f32,
